mapper.select:
SELECT role
FROM mingle_auth
WHERE user_id = #{userId}

mapper.update:
UPDATE mingle_users
SET last_login_at = SYSDATE
WHERE id = #{userId}

mapper.select:
SELECT COUNT(*)
FROM mingle_users
WHERE email = #{email}

SELECT COUNT(*)
FROM mingle_user_profiles
WHERE nickname = #{nickname}

mapper.insert:
INSERT INTO mingle_profile_photos (
    id, user_id, photo_url, is_primary, display_order
)
VALUES (
    seq_mingle_profile_photos.NEXTVAL,
    #{userId},
    #{photoUrl},
    #{isPrimary},
    #{displayOrder}
)

mapper.select:
SELECT COUNT(*)
FROM mingle_user_profiles
WHERE nickname = #{nickname}
  AND user_id != #{userId}

SELECT interest_id
FROM mingle_user_interests
WHERE user_id = #{userId}

SELECT COUNT(*)
FROM mingle_profile_photos
WHERE user_id = #{userId}

SELECT NVL(MAX(display_order), 0)
FROM mingle_profile_photos
WHERE user_id = #{userId}

mapper.delete:
DELETE FROM mingle_profile_photos
WHERE id      = #{photoId}
  AND user_id = #{userId}

mapper.update:
UPDATE mingle_profile_photos
SET is_primary = 1
WHERE id      = #{photoId}
  AND user_id = #{userId}
